<section class="page-hero small"><div class="container"><span class="eyebrow">حساب المستخدم</span><h1>مرحبًا، <?= e(\Khatauat\Core\Auth::user()['name'] ?? '') ?></h1><p>مساراتك المحفوظة، نسبة التقدم، المتابعات والتنبيهات.</p></div></section><section class="section"><div class="container dashboard-grid"><div class="dashboard-main"><div class="section-head compact"><div><span class="eyebrow">المسارات المحفوظة</span><h2>تقدمك</h2></div></div><?php if(!$paths): ?><div class="empty-state"><h3>لم تحفظ مسارًا بعد</h3><a class="btn btn-primary" href="<?= e(url('procedures')) ?>">استعرض الإجراءات</a></div><?php endif; ?><?php foreach($paths as $p): $pct=(int)$p['total_steps']?round(((int)$p['completed_steps']/(int)$p['total_steps'])*100):0; ?><article class="progress-card"><div><span class="badge"><?= $pct ?>%</span><h3><?= e($p['service_name']) ?></h3><p><?= (int)$p['completed_steps'] ?> من <?= (int)$p['total_steps'] ?> خطوات منجزة</p></div><div class="progress-bar"><span style="width:<?= $pct ?>%"></span></div><a class="text-link" href="<?= e(url('path/'.$p['slug'].(!empty($p['answers'])?'?'.http_build_query($p['answers']):''))) ?>">متابعة المسار ←</a></article><?php endforeach; ?><div class="section-head compact top-gap"><div><span class="eyebrow">التنبيهات</span><h2>آخر الإشعارات</h2></div></div><?php foreach($notifications as $n): ?><a class="notification-row" href="<?= e($n['link']?:'#') ?>"><div><b><?= e($n['title']) ?></b><p><?= e($n['message']) ?></p></div><time><?= e(substr($n['created_at'],0,16)) ?></time></a><?php endforeach; ?></div><aside><form class="form-card sticky-card" method="post" action="<?= e(url('account/settings')) ?>"><?= csrf_field() ?><span class="eyebrow">التفضيلات</span><h3>التنبيهات</h3><label class="switch-row"><span>استقبال التنبيهات</span><input type="checkbox" name="notifications_enabled" <?= (\Khatauat\Core\Auth::user()['notifications_enabled']??0)?'checked':'' ?>></label><label>التكرار<select name="notification_frequency"><option value="instant" <?= (\Khatauat\Core\Auth::user()['notification_frequency']??'')==='instant'?'selected':'' ?>>فوري</option><option value="daily" <?= (\Khatauat\Core\Auth::user()['notification_frequency']??'')==='daily'?'selected':'' ?>>ملخص يومي</option><option value="weekly" <?= (\Khatauat\Core\Auth::user()['notification_frequency']??'')==='weekly'?'selected':'' ?>>ملخص أسبوعي</option></select></label><button class="btn btn-primary" type="submit">حفظ التفضيلات</button></form></aside></div></section>
